module NecklaceDivision (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [3:0] k,\n    input wire [7:0] beads [0:15],\n    output reg result,\n    output reg done\n);\n\n    // State declarations\n    localparam [3:0] IDLE          = 4'd0;\n    localparam [3:0] SUM_BEADS     = 4'd1;\n    localparam [3:0] CHECK_TOTAL   = 4'd2;\n    localparam [3:0] BUILD_PREFIX  = 4'd3;\n    localparam [3:0] CHECK_SEG     = 4'd4;\n    localparam [3:0] SCAN_PREFIX   = 4'd5;\n    localparam [3:0] FINISH_YES    = 4'd6;\n    localparam [3:0] FINISH_NO     = 4'd7;\n\n    // Registers\n    reg [3:0] state, next_state;\n    reg [11:0] total_sum;          // 12-bit: max 4095\n    reg [11:0] target;             // 12-bit\n    reg [11:0] prefix [0:15];      // Prefix sums array (16 elements)\n    reg [3:0] idx;                 // Generic index (0-15)\n    reg [3:0] seg_idx;             // Segment index (1 to k-1)\n    reg [11:0] target_seg;         // Current target segment weight\n    reg found;                     // Flag for segment found in prefix\n    reg [7:0] temp_sum;            // Temporary sum for prefix building\n    reg [3:0] i_reg;               // Loop index for array access\n    reg [11:0] clamp_sum;          // Clamped sum\n\n    // Initialize all registers in reset\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            total_sum <= 12'd0;\n            target <= 12'd0;\n            for (i_reg = 0; i_reg < 16; i_reg = i_reg + 1) begin\n                prefix[i_reg] <= 12'd0;\n            end\n            idx <= 4'd0;\n            seg_idx <= 4'd0;\n            target_seg <= 12'd0;\n            found <= 1'b0;\n            temp_sum <= 8'd0;\n            clamp_sum <= 12'd0;\n            result <= 1'b0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    result <= 1'b0;\n                    total_sum <= 12'd0;\n                    target <= 12'd0;\n                    // Clear prefix array\n                    for (i_reg = 0; i_reg < 16; i_reg = i_reg + 1) begin\n                        prefix[i_reg] <= 12'd0;\n                    end\n                    idx <= 4'd0;\n                    seg_idx <= 4'd0;\n                    target_seg <= 12'd0;\n                    found <= 1'b0;\n                    temp_sum <= 8'd0;\n                    clamp_sum <= 12'd0;\n                    if (start) begin\n                        state <= SUM_BEADS;\n                        idx <= 4'd0;\n                    end else begin\n                        state <= IDLE;\n                    end\n                end\n\n                SUM_BEADS: begin\n                    // Accumulate total sum of all beads\n                    if (idx < n) begin\n                        // Add current bead weight\n                        clamp_sum = total_sum + beads[idx];\n                        // Clamp to 12-bit max (4095)\n                        if (clamp_sum < total_sum) begin\n                            total_sum <= 12'd4095;\n                        end else begin\n                            total_sum <= clamp_sum;\n                        end\n                        idx <= idx + 4'd1;\n                        state <= SUM_BEADS;\n                    end else begin\n                        // All beads summed\n                        state <= CHECK_TOTAL;\n                        idx <= 4'd0;\n                    end\n                end\n\n                CHECK_TOTAL: begin\n                    // Check if total_sum % k == 0\n                    if (k == 4'd0) begin\n                        state <= FINISH_NO;\n                    end else if (total_sum == 12'd0) begin\n                        // Special case: all weights zero\n                        if (n == 4'd0) begin\n                            state <= FINISH_NO;\n                        end else begin\n                            state <= BUILD_PREFIX;\n                            idx <= 4'd0;\n                            temp_sum <= 8'd0;\n                        end\n                    end else begin\n                        // Check divisibility: total_sum % k == 0\n                        // We need to check if total_sum is divisible by k\n                        // Since k ≤ 4, we can use simple comparison\n                        // Actually, for division, we need to compute total_sum / k\n                        // But first, check remainder.\n                        // Manual check for k=1,2,3,4\n                        if (k == 4'd1) begin\n                            target <= total_sum;\n                            state <= BUILD_PREFIX;\n                            idx <= 4'd0;\n                            temp_sum <= 8'd0;\n                        end else if (k == 4'd2) begin\n                            if (total_sum[0] == 1'd0) begin\n                                target <= total_sum >> 1;\n                                state <= BUILD_PREFIX;\n                                idx <= 4'd0;\n                                temp_sum <= 8'd0;\n                            end else begin\n                                state <= FINISH_NO;\n                            end\n                        end else if (k == 4'd3) begin\n                            // Check divisibility by 3 (sum of digits mod 3)\n                            // Simple: (total_sum / 3)*3 == total_sum?\n                            // Or compute division and remainder\n                            // Total sum max 4095, fits in 12 bits\n                            // Divide by 3: result is integer if divisible\n                            // We can use a loop to subtract 3, but that's slow.\n                            // Since n is small, a few cycles is ok.\n                            // Let's compute quotient and remainder.\n                            // Start a division process.\n                            state <= CHECK_SEG; // Reuse CHECK_SEG for division logic\n                            seg_idx <= 4'd0; // Will be used as temp for remainder\n                            target_seg <= total_sum;\n                            target <= 12'd0;\n                        end else if (k == 4'd4) begin\n                            if (total_sum[1:0] == 2'd0) begin\n                                target <= total_sum >> 2;\n                                state <= BUILD_PREFIX;\n                                idx <= 4'd0;\n                                temp_sum <= 8'd0;\n                            end else begin\n                                state <= FINISH_NO;\n                            end\n                        end else begin\n                            state <= FINISH_NO;\n                        end\n                    end\n                end\n\n                CHECK_SEG: begin\n                    // Special state for k=3 divisibility check\n                    // Check if total_sum % 3 == 0\n                    // target_seg holds current remainder of subtraction (starts at total_sum)\n                    if (target_seg >= 12'd3) begin\n                        target_seg <= target_seg - 12'd3;\n                        target <= target + 12'd1;\n                        state <= CHECK_SEG;\n                    end else begin\n                        // Done subtraction\n                        if (target_seg == 12'd0) begin\n                            // Divisible\n                            state <= BUILD_PREFIX;\n                            idx <= 4'd0;\n                            temp_sum <= 8'd0;\n                        end else begin\n                            // Not divisible\n                            state <= FINISH_NO;\n                        end\n                    end\n                end\n\n                BUILD_PREFIX: begin\n                    // Build prefix sums: prefix[i] = sum(beads[0]...beads[i])\n                    if (idx < n) begin\n                        temp_sum = temp_sum + beads[idx];\n                        prefix[idx] <= {4'd0, temp_sum}; // Extend to 12 bits\n                        idx <= idx + 4'd1;\n                        state <= BUILD_PREFIX;\n                    end else begin\n                        // Prefix built, also set prefix[n-1] is last valid bead sum\n                        // The definition is prefix[i] = sum of beads[0:i] (inclusive)\n                        // idx goes 0 to n-1.\n                        // We also need prefix array index n (sum of all beads)\n                        // Which is total_sum.\n                        prefix[n] <= total_sum;\n                        state <= CHECK_SEG;\n                        seg_idx <= 4'd1; // Start checking from 1*target\n                        // If k==1, we are done (always YES if divisible)\n                        if (k == 4'd1) begin\n                            state <= FINISH_YES;\n                        end\n                    end\n                end\n\n                CHECK_SEG: begin\n                    // Check if seg_idx * target exists in prefix[0...n-1]\n                    // Compute target weight for current segment\n                    // Since k <= 4, seg_idx is small (1, 2, 3)\n                    if (seg_idx == 4'd1) target_seg <= target;\n                    else if (seg_idx == 4'd2) target_seg <= {target[10:0], 1'b0}; // 2*target\n                    else if (seg_idx == 4'd3) target_seg <= target + {target[10:0], 1'b0}; // 3*target\n                    // Note: k*target = total_sum, which is prefix[n]. We only check up to (k-1)*target\n                    // So seg_idx goes 1 to k-1\n\n                    if (seg_idx < k) begin\n                        // Start scanning prefix array\n                        idx <= 4'd0;\n                        found <= 1'b0;\n                        state <= SCAN_PREFIX;\n                    end else begin\n                        // All segments checked\n                        state <= FINISH_YES;\n                    end\n                end\n\n                SCAN_PREFIX: begin\n                    // Linear scan of prefix array\n                    // Check prefix[idx] == target_seg\n                    // Scan only valid indices: 0 to n-1\n                    if (idx < n) begin\n                        if (prefix[idx] == target_seg) begin\n                            found <= 1'b1;\n                            // Found, move to next segment check\n                            // Wait for clock to latch found if needed, or jump now\n                            // Let's jump now to next segment\n                            seg_idx <= seg_idx + 4'd1;\n                            state <= CHECK_SEG;\n                        end else begin\n                            // Not found yet\n                            idx <= idx + 4'd1;\n                            state <= SCAN_PREFIX;\n                        end\n                    end else begin\n                        // Reached end of array, not found\n                        state <= FINISH_NO;\n                    end\n                end\n\n                FINISH_YES: begin\n                    result <= 1'b1;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                FINISH_NO: begin\n                    result <= 1'b0;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule